int main() {
    long long n;
    cin >> n;

    while (n >= 1) {
        bool squareFree = true;

        for (long long j = 2; j <= n / j; ++j) {
            if (n % (j * j) == 0) {
                squareFree = false;
                n /= j;
                break;
            }
        }

        if (squareFree) {
            cout << n;
            break;
        }
    }

    return 0;
}

